// StructureMap: map MedicationOverviewMin to IHE MEOW MedicationOverviewLM
// Source : PH4H Logical Model MedicationOverviewMin (with 0..* MedicationTreatmentLineMin)
// Target : IHE Pharmacy MEOW MedicationOverviewLM (1 PatientLM, 0..* MedicationTreatmentLineLM)
// FHIR version: R5 (5.0.0)

map "MedicationOverviewMinToMedicationOverviewLM" = "http://smart.who.int/ph4h/StructureMap/MedicationOverviewMinToMedicationOverviewLM"

uses "http://smart.who.int/ph4h/StructureDefinition/MedicationOverviewMin"              alias MedicationOverviewMin       as source
uses "http://smart.who.int/ph4h/StructureDefinition/MedicationTreatmentLineMin"         alias MedicationTreatmentLineMin  as source
uses "http://profiles.ihe.net/PHARM/MEOW/StructureDefinition/MedicationOverviewLM"      alias MedicationOverviewLM        as target
uses "http://profiles.ihe.net/PHARM/MEOW/StructureDefinition/PatientLM"                 alias PatientLM                   as target
uses "http://profiles.ihe.net/PHARM/MEOW/StructureDefinition/MedicationTreatmentLineLM" alias MedicationTreatmentLineLM   as target


// ---------------------------------------------------------------------------
// Top-level group: 1 patient + 0..* medication treatment lines
// ---------------------------------------------------------------------------
group MedicationOverviewMinToMedicationOverviewLM(source src : MedicationOverviewMin, target tgt : MedicationOverviewLM) {
  src       -> tgt.patient                as patient then MedicationOverviewMinToPatientLM(src, patient)                              "patient";
  src.m as line -> tgt.medicationTreatmentLine as tline   then MedicationTreatmentLineMinToMedicationTreatmentLineLM(line, tline)     "treatmentLine";
}


// ---------------------------------------------------------------------------
// MedicationOverviewMin demographic fields -> PatientLM
// ---------------------------------------------------------------------------
group MedicationOverviewMinToPatientLM(source src : MedicationOverviewMin, target tgt : PatientLM) {
  src.n   as n   -> tgt.name as hn, hn.text = n                                        "name";
  src.dob as dob -> tgt.dateOfBirth = dob                                              "dateOfBirth";
  src.s   as s   -> tgt.gender as g, g.coding as gc,
                    gc.system = 'http://hl7.org/fhir/administrative-gender',
                    gc.code   = s                                                      "gender";
  src.id  as id  -> tgt.identifier as ident then {
                      id           -> ident.value = id                                 "identifierValue";
                      src.dt as dt -> ident.type as t, t.coding as tc, tc.code = dt    "identifierType";
                    }                                                                  "identifier";
}


// ---------------------------------------------------------------------------
// One MedicationTreatmentLineMin -> one MedicationTreatmentLineLM
// ---------------------------------------------------------------------------
group MedicationTreatmentLineMinToMedicationTreatmentLineLM(source src : MedicationTreatmentLineMin, target tgt : MedicationTreatmentLineLM) {
  src.m as med -> tgt.medicationCodeableConcept as cc, cc.coding as c,
                  c.code = med, c.display = med                                        "medication";

  src -> tgt.effectivePeriod as ep then {
    src.es as es -> ep.low  = es                                                       "effLow";
    src.ee as ee -> ep.high = ee                                                       "effHigh";
  }                                                                                    "effectivePeriod";

  src.da as da -> tgt.recordingMetadata as rm, rm.recordedTime = da                    "dateAsserted";
  src.d  as d  -> tgt.comment as cmt, cmt.commentText = d                              "dosage";
  src.r  as r  -> tgt.indicationText = r                                               "reason";
  src.a  as a  -> tgt.treatmentStatus as ts, ts.coding as tsc, tsc.code = a            "adherence";
}
